// Convert an arbitrary byte string and assert basic property: size preservation.
std::string s = FUZZ_PARAM_STR();
std::vector<uint8_t> bytes = fuzztest::ToByteArray(s);
FUZZ_ASSERT(bytes.size() == s.size(), "ToByteArray must preserve size");
// Validation: Exercises conversion and asserts a fundamental, required property.

// Static, no inputs required. Validate it matches the URBG's result_type min.
auto mn = fuzztest::FuzzingBitGen::min();
FUZZ_ASSERT(mn == (std::numeric_limits<fuzztest::FuzzingBitGen::result_type>::min)(),
            "min() must equal numeric_limits<uint64_t>::min()");
// Validation summary: Called the target static function and asserted its contract.

// Static, no inputs required. Validate it matches the URBG's result_type max.
auto mx = fuzztest::FuzzingBitGen::max();
FUZZ_ASSERT(mx == (std::numeric_limits<fuzztest::FuzzingBitGen::result_type>::max)(),
            "max() must equal numeric_limits<uint64_t>::max()");
// Validation summary: Called the target static function and asserted its contract.

// Enforce that this instance was constructed with a persistent backing buffer.
if (!FUZZ_GET_ATTR_PTR(gen, "backing_buf")) { FUZZ_BAIL(); }
// Choose a random 64-bit seed value.
fuzztest::FuzzingBitGen::result_type seed_value = *FUZZ_PARAM(unsigned long long);
// Reseed the internal engine.
gen->seed(seed_value);
// Keep the same object alive by returning it as output.
// Validation summary: Ensures object validity and lifetime attribute, then exercises reseeding.
